def find_max(words):
    def count_unique_chars(word):
        return len(set(word))

    max_word = ""
    max_unique_count = -1

    for word in words:
        unique_count = count_unique_chars(word)
        if (unique_count > max_unique_count or
                (unique_count == max_unique_count and word < max_word)):
            max_word = word
            max_unique_count = unique_count

    return max_word

